-- Ground-truth labels. Keep SEPARATE from the input tables; never load into the same
-- database a detector reads from.
CREATE TABLE GroundTruth (
  case_id TEXT NOT NULL,
  issue_type TEXT NOT NULL CHECK (issue_type IN ('MACHINE_OVERLAP', 'PRECEDENCE_VIOLATED', 'MATERIAL_NOT_AVAILABLE', 'OUTSIDE_SHIFT_CALENDAR', 'CHANGEOVER_OMITTED', 'BOUNDARY_STARTS_AT_PREDECESSOR_END', 'BOUNDARY_STARTS_AT_MATERIAL_AVAILABLE', 'BOUNDARY_ENDS_AT_SHIFT_END')),
  entity_type TEXT NOT NULL CHECK (entity_type IN ('OperationSchedule')),
  entity_id TEXT NOT NULL,
  ground_truth TEXT NOT NULL CHECK (ground_truth IN ('INJECTED_VIOLATION', 'VALID_BOUNDARY')),
  expected_decision TEXT NOT NULL CHECK (expected_decision IN ('FLAG_AND_REPORT', 'ACCEPT')),
  description TEXT NOT NULL,
  PRIMARY KEY (case_id)
);
BEGIN TRANSACTION;
COMMIT;
